#!/usr/bin/env node
// Generates the hero-demo illustrations (DEVELOPMENT FIXTURES, hand-authored vector art; not StoryPanel
// output and not generated by any AI provider). One set of drawing functions is shared by every image, so
// the keeper, the gull, the lighthouse, the blue shelter and the shell look the same everywhere.
//   node scripts/hero-demo-art.mjs   ->  public/hero-demo/*.svg + src/components/hero-demo/anchors.json
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "public/hero-demo");
mkdirSync(OUT, { recursive: true });

const C = {
  skin: "#f1c29b", skinShade: "#dfa57d", cap: "#24345e", capBand: "#33497f", coat: "#f2b51a", coatShade: "#d99b0c",
  coatLine: "#a8740a", frame: "#1d2433", ink: "#1d2433", gullBody: "#fbfbf8", gullShade: "#e3e5e8", wing: "#9aa4b0",
  wingDark: "#6f7a87", beak: "#f08a24", shelter: "#2f6fd6", shelterDark: "#2456a8", roof: "#1f3f7a",
  lightWhite: "#f4efe6", lightRed: "#c8443a", lamp: "#ffe9a3", rock: "#5b5f6b", rockLight: "#737887", sea: "#2f5f72",
  seaLight: "#3f7a8f", shell: "#f6c6c0", shellLine: "#d98f88",
};

const g = (inner, t = "") => `<g${t ? ` transform="${t}"` : ""}>${inner}</g>`;

function sky(w, h, mood = "dusk") {
  const id = `sky${w}${mood}`;
  const stops = mood === "calm"
    ? [["0", "#f6b27a"], ["0.55", "#f3c9a0"], ["1", "#f7e0c3"]]
    : [["0", "#5d5a86"], ["0.5", "#c9787b"], ["1", "#f2b27c"]];
  return `<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">${stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join("")}</linearGradient></defs><rect width="${w}" height="${h}" fill="url(#${id})"/>`;
}
function sea(w, y, h) {
  let waves = "";
  for (let x = -20; x < w + 40; x += 46) waves += `<path d="M${x} ${y + 14} q 12 -7 23 0 t 23 0" fill="none" stroke="${C.seaLight}" stroke-width="3" stroke-linecap="round" opacity="0.7"/>`;
  return `<rect x="0" y="${y}" width="${w}" height="${h}" fill="${C.sea}"/>${waves}`;
}
function rain(w, h, n = 60, seed = 3, op = 0.45) {
  let s = seed, out = "";
  const rnd = () => ((s = (s * 9301 + 49297) % 233280) / 233280);
  for (let i = 0; i < n; i++) {
    const x = rnd() * w, y = rnd() * h, l = 14 + rnd() * 12;
    out += `<line x1="${x.toFixed(1)}" y1="${y.toFixed(1)}" x2="${(x - 4).toFixed(1)}" y2="${(y + l).toFixed(1)}" stroke="#e8eef5" stroke-width="2" stroke-linecap="round" opacity="${op}"/>`;
  }
  return out;
}
function lighthouse(x, y, s = 1) {
  // base at (x, y); about 90 wide, 300 tall at s = 1
  const body = `<path d="M-34 0 L-24 -250 L24 -250 L34 0 Z" fill="${C.lightWhite}" stroke="${C.ink}" stroke-width="3"/>
    <path d="M-31.5 -60 L-29 -105 L29 -105 L31.5 -60 Z" fill="${C.lightRed}"/><path d="M-27 -160 L-25.5 -200 L25.5 -200 L27 -160 Z" fill="${C.lightRed}"/>
    <rect x="-30" y="-262" width="60" height="12" rx="3" fill="${C.ink}"/><rect x="-20" y="-300" width="40" height="38" rx="4" fill="${C.lamp}" stroke="${C.ink}" stroke-width="3"/>
    <path d="M-26 -300 L0 -322 L26 -300 Z" fill="${C.lightRed}" stroke="${C.ink}" stroke-width="3" stroke-linejoin="round"/>
    <rect x="-9" y="-44" width="18" height="44" rx="8" fill="#6b4a2e" stroke="${C.ink}" stroke-width="2.5"/>
    <circle cx="0" cy="-140" r="7" fill="${C.lamp}" stroke="${C.ink}" stroke-width="2.5"/>`;
  return g(body, `translate(${x} ${y}) scale(${s})`);
}
function glow(x, y, r) {
  return `<defs><radialGradient id="gl${x}${y}"><stop offset="0" stop-color="#fff3c4" stop-opacity="0.85"/><stop offset="1" stop-color="#fff3c4" stop-opacity="0"/></radialGradient></defs><circle cx="${x}" cy="${y}" r="${r}" fill="url(#gl${x}${y})"/>`;
}
function rocks(w, y) {
  return `<path d="M0 ${y} Q ${w * 0.2} ${y - 18} ${w * 0.42} ${y - 6} T ${w} ${y - 10} L ${w} ${y + 400} L 0 ${y + 400} Z" fill="${C.rock}"/><path d="M0 ${y + 8} Q ${w * 0.3} ${y - 4} ${w * 0.6} ${y + 10} T ${w} ${y + 6}" fill="none" stroke="${C.rockLight}" stroke-width="5" stroke-linecap="round" opacity="0.6"/>`;
}

/** The keeper. Origin = feet centre; ~240 tall at s = 1. `look` -1 left / 1 right. Returns svg + head anchor. */
function keeper(x, y, s = 1, { look = 1, kneel = false, smile = false, armUp = false } = {}) {
  const lift = kneel ? 55 : 0;
  const coatH = kneel ? 95 : 140;
  const parts = [];
  // legs / boots
  if (!kneel) parts.push(`<rect x="-26" y="-36" width="20" height="36" rx="6" fill="#2b3a52"/><rect x="6" y="-36" width="20" height="36" rx="6" fill="#2b3a52"/><rect x="-30" y="-10" width="26" height="12" rx="5" fill="${C.ink}"/><rect x="4" y="-10" width="26" height="12" rx="5" fill="${C.ink}"/>`);
  else parts.push(`<ellipse cx="18" cy="-8" rx="30" ry="12" fill="#2b3a52"/><rect x="-36" y="-14" width="26" height="14" rx="6" fill="${C.ink}"/>`);
  // coat
  const top = -36 - coatH + (kneel ? 20 : 0);
  parts.push(`<path d="M-44 ${-30 + (kneel ? -2 : 0)} Q -48 ${top + 30} -30 ${top} L 30 ${top} Q 48 ${top + 30} 44 ${-30} Z" fill="${C.coat}" stroke="${C.coatLine}" stroke-width="3" stroke-linejoin="round"/>`);
  parts.push(`<path d="M0 ${top + 10} L 0 -32" stroke="${C.coatShade}" stroke-width="3"/><circle cx="-7" cy="${top + 40}" r="3" fill="${C.coatLine}"/><circle cx="-7" cy="${top + 70}" r="3" fill="${C.coatLine}"/>`);
  // collar
  parts.push(`<path d="M-24 ${top + 2} L 0 ${top + 20} L 24 ${top + 2} L 16 ${top - 8} L -16 ${top - 8} Z" fill="${C.coatShade}" stroke="${C.coatLine}" stroke-width="2.5" stroke-linejoin="round"/>`);
  // arms
  if (armUp) parts.push(`<path d="M ${30 * look} ${top + 20} Q ${62 * look} ${top + 40} ${78 * look} ${top + 70}" fill="none" stroke="${C.coat}" stroke-width="20" stroke-linecap="round"/><circle cx="${82 * look}" cy="${top + 76}" r="10" fill="${C.skin}" stroke="${C.skinShade}" stroke-width="2"/>`);
  else parts.push(`<path d="M ${34 * look} ${top + 22} Q ${50 * look} ${top + 60} ${44 * look} ${top + 92}" fill="none" stroke="${C.coat}" stroke-width="20" stroke-linecap="round"/><circle cx="${44 * look}" cy="${top + 100}" r="10" fill="${C.skin}" stroke="${C.skinShade}" stroke-width="2"/>`);
  parts.push(`<path d="M ${-34 * look} ${top + 22} Q ${-46 * look} ${top + 60} ${-40 * look} ${top + 92}" fill="none" stroke="${C.coatShade}" stroke-width="20" stroke-linecap="round"/>`);
  // head
  const hy = top - 42;
  parts.push(`<circle cx="0" cy="${hy}" r="36" fill="${C.skin}" stroke="${C.skinShade}" stroke-width="2.5"/>`);
  parts.push(`<circle cx="${-30 * look}" cy="${hy + 4}" r="8" fill="${C.skin}" stroke="${C.skinShade}" stroke-width="2"/>`);
  // cap
  parts.push(`<path d="M-37 ${hy - 6} Q -36 ${hy - 50} 0 ${hy - 52} Q 36 ${hy - 50} 37 ${hy - 6} Z" fill="${C.cap}"/><rect x="-39" y="${hy - 14}" width="78" height="15" rx="6" fill="${C.capBand}"/><circle cx="0" cy="${hy - 55}" r="9" fill="${C.capBand}"/>`);
  // glasses + eyes
  const ex = 13 * look;
  parts.push(`<circle cx="${ex - 13}" cy="${hy + 6}" r="10" fill="#fff" fill-opacity="0.35" stroke="${C.frame}" stroke-width="3.5"/><circle cx="${ex + 13}" cy="${hy + 6}" r="10" fill="#fff" fill-opacity="0.35" stroke="${C.frame}" stroke-width="3.5"/><path d="M ${ex - 3} ${hy + 6} h 6" stroke="${C.frame}" stroke-width="3"/>`);
  parts.push(`<circle cx="${ex - 13 + 2 * look}" cy="${hy + 7}" r="3.2" fill="${C.ink}"/><circle cx="${ex + 13 + 2 * look}" cy="${hy + 7}" r="3.2" fill="${C.ink}"/>`);
  // mouth + cheeks
  parts.push(smile ? `<path d="M ${ex - 9} ${hy + 22} Q ${ex} ${hy + 31} ${ex + 9} ${hy + 22}" fill="none" stroke="${C.ink}" stroke-width="3" stroke-linecap="round"/>`
    : `<path d="M ${ex - 6} ${hy + 25} Q ${ex} ${hy + 28} ${ex + 6} ${hy + 25}" fill="none" stroke="${C.ink}" stroke-width="3" stroke-linecap="round"/>`);
  parts.push(`<circle cx="${ex - 20}" cy="${hy + 20}" r="5" fill="#e98f7a" opacity="0.45"/><circle cx="${ex + 20}" cy="${hy + 20}" r="5" fill="#e98f7a" opacity="0.45"/>`);
  return {
    svg: g(parts.join(""), `translate(${x} ${y - lift * 0} ) scale(${s})`),
    head: { cx: x, cy: y + hy * s, r: 36 * s },
    glasses: { cx: x + ex * s, cy: y + (hy + 6) * s, w: 50 * s, h: 24 * s },
  };
}

/** The gull. Origin = feet centre; ~80 tall at s = 1. */
function gull(x, y, s = 1, { look = -1, huddle = false, cozy = false } = {}) {
  const p = [];
  if (!cozy) p.push(`<path d="M -6 0 v -12 M 8 0 v -12" stroke="${C.beak}" stroke-width="3.5" stroke-linecap="round"/>`);
  const by = huddle ? -26 : -32;
  p.push(`<ellipse cx="0" cy="${by}" rx="${huddle ? 30 : 26}" ry="${huddle ? 20 : 22}" fill="${C.gullBody}" stroke="${C.ink}" stroke-width="2.5"/>`);
  p.push(`<path d="M ${-24 * look} ${by - 6} Q ${4 * look} ${by - 22} ${26 * look} ${by + 2} Q ${2 * look} ${by + 10} ${-20 * look} ${by + 4} Z" fill="${C.wing}" stroke="${C.ink}" stroke-width="2.5" stroke-linejoin="round"/>`);
  p.push(`<path d="M ${24 * look} ${by + 2} l ${12 * look} 6 l ${-14 * look} 2 Z" fill="${C.wingDark}"/>`);
  const hx = -18 * look, hy = by - (huddle ? 16 : 24);
  p.push(`<circle cx="${hx}" cy="${hy}" r="${huddle ? 13 : 15}" fill="${C.gullBody}" stroke="${C.ink}" stroke-width="2.5"/>`);
  p.push(`<path d="M ${hx - 12 * look} ${hy + 1} l ${-16 * look} 4 l ${16 * look} 4 Z" fill="${C.beak}" stroke="${C.ink}" stroke-width="1.8" stroke-linejoin="round"/>`);
  p.push(`<circle cx="${hx - 4 * look}" cy="${hy - 3}" r="2.8" fill="${C.ink}"/>`);
  if (huddle) p.push(`<path d="M ${12} ${by - 18} l 6 -6 M 22 ${by - 12} l 7 -3" stroke="#e8eef5" stroke-width="2.5" stroke-linecap="round"/>`);
  if (cozy) p.push(`<path d="M ${hx - 6} ${hy - 6} q 4 -3 8 0" fill="none" stroke="${C.ink}" stroke-width="2"/>`);
  return { svg: g(p.join(""), `translate(${x} ${y}) scale(${s})`), head: { cx: x + hx * s, cy: y + hy * s, r: 15 * s } };
}

function shelter(x, y, s = 1, { open = true } = {}) {
  return g(`<rect x="-46" y="-62" width="92" height="62" rx="6" fill="${C.shelter}" stroke="${C.ink}" stroke-width="3"/>
    <path d="M-56 -58 L 0 -100 L 56 -58 Z" fill="${C.roof}" stroke="${C.ink}" stroke-width="3" stroke-linejoin="round"/>
    <path d="M-46 -40 h 92" stroke="${C.shelterDark}" stroke-width="3"/><path d="M-46 -20 h 92" stroke="${C.shelterDark}" stroke-width="3"/>
    ${open ? `<path d="M-20 0 v -26 a 20 20 0 0 1 40 0 v 26 Z" fill="#14233f"/>` : ""}`, `translate(${x} ${y}) scale(${s})`);
}
function shell(x, y, s = 1) {
  let ribs = "";
  for (let i = -3; i <= 3; i++) ribs += `<path d="M 0 22 L ${i * 9} -18" stroke="${C.shellLine}" stroke-width="2"/>`;
  return g(`<path d="M -34 -6 Q 0 -44 34 -6 L 10 22 L -10 22 Z" fill="${C.shell}" stroke="${C.ink}" stroke-width="2.5" stroke-linejoin="round"/>${ribs}
    <path d="M -10 22 h 20 v 6 h -20 Z" fill="${C.shellLine}" stroke="${C.ink}" stroke-width="2"/>
    <path d="M 30 -34 l 4 -10 l 4 10 l 10 4 l -10 4 l -4 10 l -4 -10 l -10 -4 Z" fill="#fff6c8" stroke="#e6c35a" stroke-width="1.5"/>
    <path d="M -36 -24 l 2.5 -6 l 2.5 6 l 6 2.5 l -6 2.5 l -2.5 6 l -2.5 -6 l -6 -2.5 Z" fill="#fff6c8"/>`, `translate(${x} ${y}) scale(${s})`);
}

const svgDoc = (w, h, body, title) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${title}">
<!-- StoryPanel hero demo: DEVELOPMENT FIXTURE. Hand-authored vector illustration, not StoryPanel output. Replace with approved art before publication. -->
<title>${title}</title>${body}</svg>`;
const frac = (v, total) => +(v / total).toFixed(4);
const anchors = {};

// ---- portraits 400 x 480
{
  const k = keeper(200, 470, 1.55, { look: 1, smile: true });
  writeFileSync(join(OUT, "cast-keeper.svg"), svgDoc(400, 480, `<rect width="400" height="480" fill="#f3e3cc"/><circle cx="200" cy="215" r="150" fill="#f8eedf"/>${k.svg}`, "Reference portrait: the lighthouse keeper in a yellow raincoat, navy knit cap and round glasses"));
  anchors.castKeeper = { coat: { x: frac(200, 400), y: frac(380, 480) }, glasses: { x: frac(k.glasses.cx, 400), y: frac(k.glasses.cy, 480) }, cap: { x: frac(200, 400), y: frac(k.head.cy - 60, 480) } };
  const gl = gull(200, 400, 3.2, { look: -1 });
  writeFileSync(join(OUT, "cast-gull.svg"), svgDoc(400, 480, `<rect width="400" height="480" fill="#dfe7ea"/><circle cx="200" cy="250" r="150" fill="#eef3f4"/>${gl.svg}`, "Reference portrait: the gull, white with grey wings and an orange beak"));
  anchors.castGull = { beak: { x: frac(gl.head.cx - 40, 400), y: frac(gl.head.cy + 8, 480) }, wing: { x: frac(200, 400), y: frac(320, 480) } };
}

// ---- panel 1 (580 x 400): wide. The keeper notices the gull in the rain. No shell.
{
  const W = 580, H = 400;
  const k = keeper(170, 352, 0.82, { look: 1 });
  const gl = gull(408, 345, 0.95, { look: -1, huddle: true });
  const body = `${sky(W, H)}${glow(470, 70, 70)}${sea(W, 250, 150)}${lighthouse(470, 330, 0.95)}${rocks(W, 330)}${gl.svg}${k.svg}${rain(W, H, 70, 7)}`;
  writeFileSync(join(OUT, "panel-1.svg"), svgDoc(W, H, body, "Panel 1: at dusk in the rain, the keeper notices a shivering gull at the foot of the lighthouse"));
  anchors.panel1 = { keeperHead: { x: frac(k.head.cx, W), y: frac(k.head.cy, H) }, glasses: { x: frac(k.glasses.cx, W), y: frac(k.glasses.cy, H) }, gullHead: { x: frac(gl.head.cx, W), y: frac(gl.head.cy, H) } };
}
// ---- panel 2 (580 x 400): medium. The keeper places the blue shelter. No shell.
{
  const W = 580, H = 400;
  const k = keeper(205, 380, 1.05, { look: 1, kneel: true, armUp: true });
  const gl = gull(470, 372, 1.1, { look: -1 });
  const body = `${sky(W, H)}${sea(W, 230, 170)}<rect x="0" y="0" width="120" height="${H}" fill="${C.lightWhite}"/><rect x="0" y="120" width="120" height="60" fill="${C.lightRed}"/><path d="M120 0 V ${H}" stroke="${C.ink}" stroke-width="3"/>${rocks(W, 360)}${shelter(330, 372, 1.15)}${gl.svg}${k.svg}${rain(W, H, 60, 11)}`;
  writeFileSync(join(OUT, "panel-2.svg"), svgDoc(W, H, body, "Panel 2: the keeper kneels and sets a small blue shelter beside the lighthouse while the gull watches"));
  anchors.panel2 = { keeperHead: { x: frac(k.head.cx, W), y: frac(k.head.cy, H) }, glasses: { x: frac(k.glasses.cx, W), y: frac(k.glasses.cy, H) }, shelter: { x: frac(330, W), y: frac(330, H) } };
}
// ---- panel 3 (1120 x 460): close-up payoff. Gull safe inside; the keeper finds the shell.
{
  const W = 1120, H = 460;
  const k = keeper(800, 540, 1.9, { look: -1, smile: true, armUp: true });
  const gl = gull(400, 392, 1.45, { look: 1, cozy: true });
  const body = `${sky(W, H, "calm")}${sea(W, 300, 160)}${rocks(W, 420)}${shelter(400, 430, 2.3)}${g(gl.svg, "")}${k.svg}${shell(646, 318, 1.25)}${rain(W, H, 30, 5, 0.25)}`;
  writeFileSync(join(OUT, "panel-3.svg"), svgDoc(W, H, body, "Panel 3: the gull is warm inside the blue shelter, and the smiling keeper holds a shiny shell left as thanks"));
  anchors.panel3 = { keeperHead: { x: frac(k.head.cx, W), y: frac(k.head.cy, H) }, glasses: { x: frac(k.glasses.cx, W), y: frac(k.glasses.cy, H) }, shell: { x: frac(646, W), y: frac(306, H) }, gullHead: { x: frac(gl.head.cx, W), y: frac(gl.head.cy, H) } };
}

writeFileSync(join(ROOT, "src/components/hero-demo/anchors.json"), JSON.stringify(anchors, null, 1) + "\n");
console.log("wrote", OUT, Object.keys(anchors));
